// Package gen generates project files from platformgo.yaml.
//
// It produces the module wiring, their settings and the environment example. This is
// what removes manual edits when modules are added or removed: only the domain part
// stays in project code.
package gen

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"text/template"

	"github.com/aidarbn/platform-go/internal/registry"
	"github.com/aidarbn/platform-go/internal/spec"
)

// Paths of generated files, relative to the project root.
const (
	ConfigPath  = "cmd/app/config.gen.go"
	ModulesPath = "cmd/app/modules.gen.go"
	EnvPath     = ".env.example"
	ComposePath = "docker-compose.yml"

	// MigrationsPath embeds the SQL migrations of the project next to them.
	MigrationsPath = "db/migrations/migrations.gen.go"
)

const migrationsGo = header + `
// Package migrations holds the SQL migrations of the project. Create one with
// platformgo migrate create <name>; the postgres module applies them on start.
package migrations

import "embed"

// FS is the migrations directory. The postgres module reads only the *.sql files in it.
//
//go:embed *
var FS embed.FS
`

const header = "// Code generated by platformgo from " + spec.FileName + ". Do not edit.\n"

var configTmpl = template.Must(template.New("config").Parse(header + `
package main

import (
{{- range .Imports}}
	{{.}}
{{- end}}
)

// Config holds settings of the platform modules of {{.Service}}.
type Config struct {
{{- range .Modules}}
	{{.Field}} {{.ConfigType}}
{{- end}}
}

// LoadConfig reads module settings from environment variables and returns every
// problem at once instead of one per restart.
func LoadConfig() (*Config, error) {
	l := confx.New("")
	cfg := &Config{
{{- range .Modules}}
		{{.Field}}: {{.LoadCall}},
{{- end}}
	}
	if err := l.Err(); err != nil {
		return nil, err
	}
	return cfg, nil
}
`))

var modulesTmpl = template.Must(template.New("modules").Parse(header + `
package main

import (
{{- range .Imports}}
	{{.}}
{{- end}}
)

// serviceName is the service name from platformgo.yaml.
const serviceName = "{{.Service}}"

// platformModules returns the project modules in dependency order.
func platformModules(cfg *Config) []platform.Module {
	return []platform.Module{
{{- range .Modules}}
		{{.NewCall}},
{{- end}}
	}
}
`))

type templateData struct {
	Service string
	Imports []string
	Modules []registry.Module
}

// Wiring returns the generated files: path relative to the project root to content.
func Wiring(f *spec.File) (map[string][]byte, error) {
	modules := f.EnabledModules()

	config, err := render(configTmpl, templateData{
		Service: f.Service(),
		Imports: configImports(modules),
		Modules: modules,
	})
	if err != nil {
		return nil, fmt.Errorf("%s: %w", ConfigPath, err)
	}

	mods, err := render(modulesTmpl, templateData{
		Service: f.Service(),
		Imports: modulesImports(f, modules),
		Modules: modules,
	})
	if err != nil {
		return nil, fmt.Errorf("%s: %w", ModulesPath, err)
	}

	files := map[string][]byte{
		ConfigPath:  config,
		ModulesPath: mods,
		EnvPath:     env(f, modules),
		ComposePath: compose(f, modules),
	}
	if _, ok := f.Modules["postgres"]; ok {
		files[MigrationsPath] = []byte(migrationsGo)
		files[SqlcPath] = []byte(sqlcYAML)
	}
	if _, ok := f.Modules["api"]; ok {
		for path, content := range apiFiles(f) {
			files[path] = content
		}
	}
	return files, nil
}

// importSpec is one import of a generated file. An alias is needed when a package
// generated in the project has the same name as a platform module.
type importSpec struct {
	Path  string
	Alias string
}

func (i importSpec) String() string {
	if i.Alias == "" || i.Alias == path.Base(i.Path) {
		return strconv.Quote(i.Path)
	}
	return i.Alias + " " + strconv.Quote(i.Path)
}

// configImports are the imports of config.gen.go: the settings types of the modules.
func configImports(modules []registry.Module) []string {
	specs := []importSpec{{Path: "github.com/aidarbn/platform-go/kit/confx"}}
	for _, m := range modules {
		specs = append(specs, importSpec{Path: m.Import})
	}
	return renderImports(specs)
}

// modulesImports are the imports of modules.gen.go. Besides the modules themselves it
// covers the packages generated in the project that a module needs at startup, such as
// the settings schema.
func modulesImports(f *spec.File, modules []registry.Module) []string {
	specs := []importSpec{{Path: "github.com/aidarbn/platform-go/kit/platform"}}
	for _, m := range modules {
		specs = append(specs, importSpec{Path: m.Import})
		if m.ProjectPkg != "" {
			specs = append(specs, importSpec{
				Path:  f.Project.Module + "/" + m.ProjectPkg,
				Alias: m.ProjectAlias,
			})
		}
	}
	return renderImports(specs)
}

func renderImports(specs []importSpec) []string {
	slices.SortFunc(specs, func(a, b importSpec) int { return strings.Compare(a.Path, b.Path) })

	out := make([]string, 0, len(specs))
	seen := make(map[string]bool, len(specs))
	for _, spec := range specs {
		if seen[spec.Path] {
			continue
		}
		seen[spec.Path] = true
		out = append(out, spec.String())
	}
	return out
}

func render(t *template.Template, data templateData) ([]byte, error) {
	return renderTemplate(t, data)
}

// renderTemplate formats what a template produced: generated code must pass gofmt in
// the project CI, and gofmt also orders the imports.
func renderTemplate(t *template.Template, data any) ([]byte, error) {
	var buf bytes.Buffer
	if err := t.Execute(&buf, data); err != nil {
		return nil, err
	}
	out, err := format.Source(buf.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format: %w", err)
	}
	return out, nil
}

func env(f *spec.File, modules []registry.Module) []byte {
	var b strings.Builder
	b.WriteString("# Generated by platformgo from " + spec.FileName + ". Do not edit.\n")
	b.WriteString("# Service: " + f.Service() + "\n")

	for _, m := range modules {
		if len(m.Env) == 0 {
			continue
		}
		b.WriteString("\n# module " + m.Name + "\n")
		for _, v := range m.Env {
			if v.Comment != "" {
				b.WriteString("# " + v.Comment)
				if v.Required {
					b.WriteString(" (required)")
				}
				b.WriteString("\n")
			}
			b.WriteString(v.Key + "=" + v.Example + "\n")
		}
	}
	return []byte(b.String())
}

// compose builds the local services of the enabled modules. The file is always there,
// so removing the last module with a service also removes the service.
func compose(f *spec.File, modules []registry.Module) []byte {
	var b strings.Builder
	b.WriteString("# Generated by platformgo from " + spec.FileName + ". Do not edit.\n")
	b.WriteString("# Local services of the enabled modules. Services of your own go into\n")
	b.WriteString("# docker-compose.override.yml, which docker compose merges automatically.\n\n")
	b.WriteString("name: " + composeName(f.Service()) + "\n\n")

	var services, volumes []string
	for _, m := range modules {
		if m.Compose != "" {
			services = append(services, strings.TrimRight(m.Compose, "\n"))
		}
		volumes = append(volumes, m.Volumes...)
	}

	if len(services) == 0 {
		b.WriteString("services: {}\n")
		return []byte(b.String())
	}
	b.WriteString("services:\n" + strings.Join(services, "\n\n") + "\n")

	if len(volumes) > 0 {
		b.WriteString("\nvolumes:\n")
		for _, v := range volumes {
			b.WriteString("  " + v + ":\n")
		}
	}
	return []byte(b.String())
}

// composeName is the compose project name: docker compose accepts lower case letters,
// digits, dash and underscore only.
func composeName(service string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(service) {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-', r == '_':
			b.WriteRune(r)
		default:
			b.WriteRune('-')
		}
	}
	if b.Len() == 0 {
		return "app"
	}
	return b.String()
}

// Files returns everything platformgo generates for the project: the module wiring and,
// when the settings module is enabled, the typed access to the business settings.
//
// The schema is read from the project directory, so the generated code always matches
// the file a developer just edited.
func Files(dir string, f *spec.File) (map[string][]byte, error) {
	return FilesFrom(f, func(path string) ([]byte, error) {
		return os.ReadFile(filepath.Join(dir, path))
	})
}

// FilesFrom is Files with the project files read through read. apply uses it to
// generate from files it is about to create, before they are on disk.
func FilesFrom(f *spec.File, read func(path string) ([]byte, error)) (map[string][]byte, error) {
	files, err := Wiring(f)
	if err != nil {
		return nil, err
	}
	if !SettingsEnabled(f) {
		return files, nil
	}

	path := SettingsSchemaPath(f)
	raw, err := read(path)
	if err != nil {
		return nil, fmt.Errorf("module settings: %s: %w", path, err)
	}
	code, err := SettingsCode(raw)
	if err != nil {
		return nil, err
	}
	files[SettingsPath] = code
	return files, nil
}

// IsGenerated reports whether content carries the mark platformgo puts on the files it
// generates. A generated file that lost the mark has been taken over by hand, and apply
// leaves it alone.
func IsGenerated(content []byte) bool {
	first, _, _ := strings.Cut(string(content), "\n")
	return strings.Contains(strings.ToLower(first), "generated by platformgo")
}

// Changed returns the paths whose content in the project differs from the generated
// one. An empty list means generation is up to date.
func Changed(dir string, files map[string][]byte) ([]string, error) {
	var changed []string
	for path, want := range files {
		got, err := os.ReadFile(filepath.Join(dir, path))
		if err != nil {
			if os.IsNotExist(err) {
				changed = append(changed, path)
				continue
			}
			return nil, fmt.Errorf("%s: %w", path, err)
		}
		if !bytes.Equal(got, want) {
			changed = append(changed, path)
		}
	}
	slices.Sort(changed)
	return changed, nil
}

// Apply writes the generated files that differ from what the project has and returns
// their paths. Untouched files keep their modification time, so a build that runs
// generation first does not rebuild everything.
func Apply(dir string, files map[string][]byte) ([]string, error) {
	paths, err := Changed(dir, files)
	if err != nil {
		return nil, err
	}

	for _, path := range paths {
		full := filepath.Join(dir, path)
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			return nil, fmt.Errorf("%s: %w", path, err)
		}
		if err := os.WriteFile(full, files[path], 0o644); err != nil {
			return nil, fmt.Errorf("%s: %w", path, err)
		}
	}
	return paths, nil
}
